text:
Service × Model × Benchmark Intersection

  Which models appear on which services, and which benchmark categories each model was tested on.
  Models that appear on more than one service are highlighted — enabling direct cross-service performance comparisons.


  Model Availability Matrix
  Each row is a model family. Filled cells indicate the model was evaluated on that service for that category. Models shared across services are shown with a ★ indicator.



services_order = ["grit", "CIT", "aicommons"]
service_colors = ({
  "grit":      "#58a6ff",
  "CIT":       "#3fb950",
  "aicommons": "#bc8cff"
})
service_labels = ({ "grit": "GRIT", "CIT": "CIT", "aicommons": "AICommons" })

// Build a map: model → [services it appears on]
model_service_map = {
  const map = {};
  for (const row of lb) {
    if (!map[row.model]) map[row.model] = { model: row.model, services: [], infra: row.infra };
    map[row.model].services.push(row.service);
  }
  return map;
}

// Enrich families with which services they appear on
families_enriched = families.map(f =&gt; {
  const svcs = Object.keys(f.services);
  const shared = svcs.length &gt; 1;
  return { ...f, service_list: svcs, shared };
})

// Categories present in summary data
cats_all = ["code_generation","metadata_generation","literature_synthesis",
            "data_interpretation","ocr","document_extraction","vision_qa"]
cat_labels_map = ({
  "code_generation":     "Code Gen",
  "metadata_generation": "Metadata Gen",
  "literature_synthesis":"Lit. Synthesis",
  "data_interpretation": "Data Interp.",
  "ocr":                 "OCR",
  "document_extraction": "Doc Extract.",
  "vision_qa":           "Vision QA"
})

// Build lookup: service+model → set of categories tested
svc_model_cats = {
  const map = {};
  for (const row of summary) {
    const k = row.service + "|||" + row.model;
    if (!map[k]) map[k] = new Set();
    map[k].add(row.category);
  }
  return map;
}


























































{
  // ── Dimensions ──────────────────────────────────────────────────────────
  const cellSize  = 22;
  const cellGap   = 3;
  const rowH      = cellSize + cellGap + 10;
  const leftPad   = 185;          // space for family name
  const topPad    = 90;
  const svcGap    = 18;           // gap between service groups
  const catCols   = cats_all.length;

  // Column layout: for each service, catCols category columns
  // services in order: grit, CIT, aicommons
  const svcsOrdered = ["grit","CIT","aicommons"];
  const svcCols     = svcsOrdered.length;

  // Total width
  const groupW  = catCols * (cellSize + cellGap);
  const totalW  = leftPad + svcCols * groupW + (svcCols - 1) * svcGap + 40;
  const totalH  = topPad + families_enriched.length * rowH + 30;

  const svg = d3.create("svg")
    .attr("width",  totalW)
    .attr("height", totalH)
    .style("font-family", "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif")
    .style("background", "transparent");

  // ── Service group headers ────────────────────────────────────────────────
  svcsOrdered.forEach((svc, si) =&gt; {
    const gx = leftPad + si * (groupW + svcGap);
    const midX = gx + groupW / 2;

    // Service label
    svg.append("text")
      .attr("x", midX).attr("y", 18)
      .attr("text-anchor", "middle")
      .attr("font-size", 13).attr("font-weight", 700)
      .attr("fill", service_colors[svc])
      .text(service_labels[svc]);

    // Infra badge text
    const infraText = svc === "aicommons" ? "☁ Amazon Bedrock" : "🖥 Ollama";
    svg.append("text")
      .attr("x", midX).attr("y", 33)
      .attr("text-anchor", "middle")
      .attr("font-size", 9.5).attr("fill", "#8b949e")
      .text(infraText);

    // Category column headers (rotated)
    cats_all.forEach((cat, ci) =&gt; {
      const cx = gx + ci * (cellSize + cellGap) + cellSize / 2;
      svg.append("text")
        .attr("transform", `translate(${cx},${topPad - 6}) rotate(-45)`)
        .attr("text-anchor", "start")
        .attr("font-size", 9.5)
        .attr("fill", "#8b949e")
        .text(cat_labels_map[cat]);
    });

    // Vertical divider between service groups
    if (si &gt; 0) {
      svg.append("line")
        .attr("x1", gx - svcGap / 2).attr("y1", 0)
        .attr("x2", gx - svcGap / 2).attr("y2", totalH)
        .attr("stroke", "#30363d").attr("stroke-width", 1).attr("stroke-dasharray", "4,3");
    }
  });

  // ── Model rows ───────────────────────────────────────────────────────────
  families_enriched.forEach((fam, fi) =&gt; {
    const ry = topPad + fi * rowH;

    // Alternating row background
    if (fi % 2 === 0) {
      svg.append("rect")
        .attr("x", 0).attr("y", ry - 2)
        .attr("width", totalW).attr("height", rowH)
        .attr("fill", "rgba(255,255,255,0.015)").attr("rx", 2);
    }

    // Family name
    const isShared = fam.service_list.length &gt; 1;
    svg.append("text")
      .attr("x", leftPad - 10).attr("y", ry + cellSize / 2 + 4)
      .attr("text-anchor", "end")
      .attr("font-size", 11.5)
      .attr("font-weight", isShared ? 700 : 400)
      .attr("fill", isShared ? "#e6edf3" : "#8b949e")
      .text((isShared ? "★ " : "") + fam.family);

    // Cells
    svcsOrdered.forEach((svc, si) =&gt; {
      const gx = leftPad + si * (groupW + svcGap);
      const modelId = fam.services[svc];  // e.g. "gemma4:31b" or undefined

      cats_all.forEach((cat, ci) =&gt; {
        const cx = gx + ci * (cellSize + cellGap);
        let fill = "#1c2128";   // empty
        let opacity = 1;
        let stroke = "#30363d";

        if (modelId) {
          const k = svc + "|||" + modelId;
          const catsForModel = svc_model_cats[k];
          if (catsForModel && catsForModel.has(cat)) {
            fill    = service_colors[svc];
            opacity = 0.85;
            stroke  = "none";
          } else if (catsForModel) {
            // model exists on service but wasn't tested on this category
            fill    = "rgba(255,255,255,0.04)";
            stroke  = "#30363d";
          }
          // else: model not on this service → stays empty
        }

        svg.append("rect")
          .attr("x", cx).attr("y", ry)
          .attr("width", cellSize).attr("height", cellSize)
          .attr("rx", 3)
          .attr("fill", fill)
          .attr("opacity", opacity)
          .attr("stroke", stroke)
          .attr("stroke-width", 0.5);
      });
    });
  });

  // ── Legend ───────────────────────────────────────────────────────────────
  const ly = totalH - 22;
  const legendItems = [
    { color: "#58a6ff", label: "GRIT" },
    { color: "#3fb950", label: "CIT" },
    { color: "#bc8cff", label: "AICommons" },
    { color: "rgba(255,255,255,0.04)", label: "Not tested (model available)", stroke: "#30363d" },
    { color: "#1c2128", label: "Model not on service", stroke: "#30363d" },
  ];
  let lx = leftPad;
  legendItems.forEach(item =&gt; {
    svg.append("rect")
      .attr("x", lx).attr("y", ly)
      .attr("width", 11).attr("height", 11).attr("rx", 2)
      .attr("fill", item.color)
      .attr("stroke", item.stroke || "none").attr("stroke-width", 0.5);
    svg.append("text")
      .attr("x", lx + 14).attr("y", ly + 9.5)
      .attr("font-size", 9.5).attr("fill", "#8b949e")
      .text(item.label);
    lx += item.label.length * 6.5 + 22;
  });

  return svg.node();
}

Overall Leaderboard

  All evaluated models ranked by overall average score (1–5 scale), then by throughput.
  Literature Synthesis scores use Claude as the canonical judge.
  Click column headers to sort.





cat_cols = [
  { key: "score_code_generation",     label: "Code Gen" },
  { key: "score_metadata_generation", label: "Metadata" },
  { key: "score_literature_synthesis",label: "Lit. Synth" },
  { key: "score_data_interpretation", label: "Data Interp" },
  { key: "score_ocr",                 label: "OCR" },
  { key: "score_vision_qa",           label: "Vision QA" },
]

function scoreCell(v) {
  if (v === null || v === undefined) return `&lt;span style="color:#6e7681"&gt;—&lt;/span&gt;`;
  const cls = v &gt;= 5 ? "score-5" : v &gt;= 4 ? "score-4" : v &gt;= 3 ? "score-3" : v &gt;= 2 ? "score-2" : "score-1";
  return `&lt;span class="${cls}"&gt;${v.toFixed(2)}&lt;/span&gt;`;
}

function svcBadge(svc) {
  const cls = svc === "grit" ? "badge-grit" : svc === "CIT" ? "badge-cit" : "badge-aicommons";
  const lbl = svc === "grit" ? "GRIT" : svc === "CIT" ? "CIT" : "AICommons";
  return `&lt;span class="service-badge ${cls}"&gt;${lbl}&lt;/span&gt;`;
}

function infraTag(row) {
  if (row.infra_type === "onprem")
    return `&lt;span style="font-size:0.72rem;color:#58a6ff"&gt;🖥 On-prem&lt;/span&gt;`;
  return `&lt;span style="font-size:0.72rem;color:#bc8cff"&gt;☁ Bedrock&lt;/span&gt;`;
}






























viewof sortCol = Inputs.select(
  ["overall_score", "avg_tps", "avg_latency_sec",
   "score_code_generation","score_metadata_generation",
   "score_literature_synthesis","score_data_interpretation",
   "score_ocr","score_vision_qa"],
  { value: "overall_score",
    label: "Sort by",
    format: v =&gt; ({
      overall_score: "Overall Score",
      avg_tps: "Throughput (TPS)",
      avg_latency_sec: "Latency (sec)",
      score_code_generation: "Code Generation",
      score_metadata_generation: "Metadata Generation",
      score_literature_synthesis: "Literature Synthesis",
      score_data_interpretation: "Data Interpretation",
      score_ocr: "OCR",
      score_vision_qa: "Vision QA"
    })[v]
  }
)







{
  const sorted = [...lb].sort((a, b) =&gt; {
    const av = a[sortCol] ?? -1;
    const bv = b[sortCol] ?? -1;
    if (sortCol === "avg_latency_sec") return av - bv; // lower is better
    return bv - av;
  });

  const rows = sorted.map((r, i) =&gt; `
    &lt;tr&gt;
      &lt;td style="color:#8b949e;font-size:0.8rem"&gt;${i + 1}&lt;/td&gt;
      &lt;td&gt;${svcBadge(r.service)}&lt;/td&gt;
      &lt;td style="font-size:0.85rem;color:#e6edf3;font-weight:500"&gt;${r.model}&lt;/td&gt;
      &lt;td&gt;${infraTag(r)}&lt;/td&gt;
      &lt;td style="text-align:center"&gt;&lt;strong style="color:#FEBC11"&gt;${r.overall_score.toFixed(2)}&lt;/strong&gt;&lt;/td&gt;
      ${cat_cols.map(c =&gt; `&lt;td style="text-align:center"&gt;${scoreCell(r[c.key])}&lt;/td&gt;`).join("")}
      &lt;td style="text-align:right;color:#8b949e;font-size:0.85rem"&gt;${r.avg_tps.toFixed(0)}&lt;/td&gt;
      &lt;td style="text-align:right;color:#8b949e;font-size:0.85rem"&gt;${r.avg_latency_sec.toFixed(2)}s&lt;/td&gt;
    &lt;/tr&gt;
  `).join("");

  const html = `
    &lt;table style="width:100%;border-collapse:collapse;"&gt;
      &lt;thead&gt;
        &lt;tr&gt;
          &lt;th&gt;#&lt;/th&gt;
          &lt;th&gt;Service&lt;/th&gt;
          &lt;th&gt;Model&lt;/th&gt;
          &lt;th&gt;Infra&lt;/th&gt;
          &lt;th style="text-align:center"&gt;Overall&lt;/th&gt;
          ${cat_cols.map(c =&gt; `&lt;th style="text-align:center"&gt;${c.label}&lt;/th&gt;`).join("")}
          &lt;th style="text-align:right"&gt;TPS&lt;/th&gt;
          &lt;th style="text-align:right"&gt;Latency&lt;/th&gt;
        &lt;/tr&gt;
      &lt;/thead&gt;
      &lt;tbody&gt;${rows}&lt;/tbody&gt;
    &lt;/table&gt;`;
  return html;
}

How do GRIT, CIT, and AICommons compare as AI platforms?
    This page examines scores by category, the speed-vs-accuracy trade-off,
    and — critically — how the same model behaves when hosted on different infrastructure.
summary  = FileAttachment("data/results_summary.csv").csv({ typed: true })
lb       = FileAttachment("data/leaderboard.json").json()

service_colors = ({
  "grit":      "#58a6ff",
  "CIT":       "#3fb950",
  "aicommons": "#bc8cff"
})
service_labels = ({ "grit": "GRIT", "CIT": "CIT", "aicommons": "AICommons" })

cat_labels_map = ({
  "code_generation":     "Code Generation",
  "metadata_generation": "Metadata Generation",
  "literature_synthesis":"Literature Synthesis",
  "data_interpretation": "Data Interpretation",
  "ocr":                 "OCR",
  "document_extraction": "Document Extraction",
  "vision_qa":           "Vision QA"
})

// Canonical: for lit_synthesis prefer claude judge; deduplicate
canonical_summary = {
  const map = new Map();
  for (const row of summary) {
    const k = row.service + "|||" + row.model + "|||" + row.category;
    const existing = map.get(k);
    if (!existing) { map.set(k, row); }
    else if (row.judge_model === "claude-v4.6-sonnet") { map.set(k, row); }
  }
  return [...map.values()];
}

svcs = ["grit","CIT","aicommons"]
cats_text = ["code_generation","metadata_generation","literature_synthesis","data_interpretation"]
cats_all  = [...cats_text, "ocr", "document_extraction", "vision_qa"]

Average Score by Category

  Mean score (1–5) per service per benchmark category, averaged across all models on that service.
  Scores use the canonical judge (Claude for literature synthesis).


  Avg Score per Category, by Service
  Bar height = mean score across all models on that service. Max = 5.0



{
  // Aggregate: service × category → mean avg_score
  const agg = {};
  for (const row of canonical_summary) {
    const k = row.service + "|||" + row.category;
    if (!agg[k]) agg[k] = { scores: [], service: row.service, category: row.category };
    agg[k].scores.push(row.avg_score);
  }

  const data = Object.values(agg).map(d =&gt; ({
    service:  d.service,
    category: d.category,
    cat_label: cat_labels_map[d.category] || d.category,
    mean_score: d.scores.reduce((a,b)=&gt;a+b,0) / d.scores.length
  }));

  // Only categories with data
  const cats_present = [...new Set(data.map(d=&gt;d.category))];
  const cat_order = cats_all.filter(c =&gt; cats_present.includes(c));

  const width  = 820;
  const height = 340;
  const marginL = 48, marginB = 90, marginT = 20, marginR = 20;
  const plotW = width - marginL - marginR;
  const plotH = height - marginT - marginB;

  // Outer scale: categories
  const x0 = d3.scaleBand()
    .domain(cat_order)
    .range([0, plotW])
    .paddingInner(0.25);

  // Inner scale: services
  const x1 = d3.scaleBand()
    .domain(svcs)
    .range([0, x0.bandwidth()])
    .paddingInner(0.08);

  const y = d3.scaleLinear().domain([0, 5]).range([plotH, 0]);

  const svg = d3.create("svg")
    .attr("width", width).attr("height", height)
    .style("font-family", "-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif")
    .style("overflow","visible");

  const g = svg.append("g").attr("transform", `translate(${marginL},${marginT})`);

  // Grid lines
  [1,2,3,4,5].forEach(v =&gt; {
    g.append("line")
      .attr("x1",0).attr("x2",plotW)
      .attr("y1",y(v)).attr("y2",y(v))
      .attr("stroke","#30363d").attr("stroke-dasharray","3,3");
    g.append("text")
      .attr("x",-6).attr("y",y(v)+4)
      .attr("text-anchor","end")
      .attr("font-size",10).attr("fill","#8b949e")
      .text(v);
  });

  // Bars
  cat_order.forEach(cat =&gt; {
    const catData = data.filter(d =&gt; d.category === cat);
    const gx = g.append("g").attr("transform", `translate(${x0(cat)},0)`);
    svcs.forEach(svc =&gt; {
      const d = catData.find(r =&gt; r.service === svc);
      if (!d) return;
      const bx = x1(svc);
      const by = y(d.mean_score);
      const bh = plotH - by;
      // Bar
      gx.append("rect")
        .attr("x",bx).attr("y",by)
        .attr("width",x1.bandwidth()).attr("height",bh)
        .attr("rx",3)
        .attr("fill", service_colors[svc])
        .attr("opacity", 0.85);
      // Value label
      if (bh &gt; 14) {
        gx.append("text")
          .attr("x", bx + x1.bandwidth()/2).attr("y", by - 4)
          .attr("text-anchor","middle")
          .attr("font-size",9.5).attr("fill","#e6edf3")
          .text(d.mean_score.toFixed(2));
      }
    });
  });

  // X axis labels
  cat_order.forEach(cat =&gt; {
    g.append("text")
      .attr("transform", `translate(${x0(cat) + x0.bandwidth()/2},${plotH+12}) rotate(-30)`)
      .attr("text-anchor","end")
      .attr("font-size",11).attr("fill","#8b949e")
      .text(cat_labels_map[cat] || cat);
  });

  // Legend
  const lx = plotW - svcs.length * 90;
  svcs.forEach((svc, i) =&gt; {
    g.append("rect")
      .attr("x", lx + i*90).attr("y", plotH + 55)
      .attr("width",11).attr("height",11).attr("rx",2)
      .attr("fill", service_colors[svc]);
    g.append("text")
      .attr("x", lx + i*90 + 14).attr("y", plotH + 64)
      .attr("font-size",11).attr("fill","#8b949e")
      .text(service_labels[svc]);
  });

  return svg.node();
}

Speed vs. Accuracy

  Each dot represents one model on one service. X-axis = average throughput (tokens/sec),
  Y-axis = overall average score. Dot size = number of categories tested.
  The ideal model sits in the top-right corner: fast and accurate.


  Throughput vs. Accuracy — All Models
  Hover over a dot to see model details. Colored by service.



{
  const width  = 780;
  const height = 420;
  const mL=70, mB=55, mT=20, mR=30;
  const pW = width-mL-mR;
  const pH = height-mT-mB;

  const x = d3.scaleLinear()
    .domain([0, d3.max(lb, d=&gt;d.avg_tps)*1.08])
    .range([0, pW]);

  const y = d3.scaleLinear().domain([0, 5.3]).range([pH, 0]);

  const rScale = d3.scaleSqrt()
    .domain([1, d3.max(lb, d=&gt;d.categories_tested)])
    .range([5, 12]);

  const svg = d3.create("svg")
    .attr("width", width).attr("height", height)
    .style("font-family","-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif")
    .style("overflow","visible");

  const g = svg.append("g").attr("transform",`translate(${mL},${mT})`);

  // Grid
  x.ticks(6).forEach(v =&gt; {
    g.append("line").attr("x1",x(v)).attr("x2",x(v)).attr("y1",0).attr("y2",pH)
     .attr("stroke","#30363d").attr("stroke-dasharray","3,3");
  });
  y.ticks(5).forEach(v =&gt; {
    g.append("line").attr("x1",0).attr("x2",pW).attr("y1",y(v)).attr("y2",y(v))
     .attr("stroke","#30363d").attr("stroke-dasharray","3,3");
    g.append("text").attr("x",-8).attr("y",y(v)+4)
     .attr("text-anchor","end").attr("font-size",10).attr("fill","#8b949e")
     .text(v);
  });
  x.ticks(6).forEach(v =&gt; {
    g.append("text").attr("x",x(v)).attr("y",pH+16)
     .attr("text-anchor","middle").attr("font-size",10).attr("fill","#8b949e")
     .text(v);
  });

  // Axis labels
  g.append("text").attr("x",pW/2).attr("y",pH+40)
   .attr("text-anchor","middle").attr("font-size",12).attr("fill","#8b949e")
   .text("Average Throughput (tokens / sec)");
  g.append("text")
   .attr("transform",`translate(-52,${pH/2}) rotate(-90)`)
   .attr("text-anchor","middle").attr("font-size",12).attr("fill","#8b949e")
   .text("Overall Average Score");

  // Points
  const tooltip = d3.select("body").select("#scatter-tooltip").node()
    ? d3.select("#scatter-tooltip")
    : d3.select("body").append("div")
        .attr("id","scatter-tooltip")
        .style("position","fixed").style("pointer-events","none")
        .style("background","#1c2128").style("border","1px solid #30363d")
        .style("border-radius","6px").style("padding","8px 12px")
        .style("font-size","12px").style("color","#e6edf3")
        .style("display","none").style("z-index","9999").style("max-width","220px");

  lb.forEach(d =&gt; {
    const cx = x(d.avg_tps);
    const cy = y(d.overall_score);
    const r  = rScale(d.categories_tested);

    g.append("circle")
      .attr("cx",cx).attr("cy",cy).attr("r",r)
      .attr("fill", service_colors[d.service])
      .attr("opacity",0.8)
      .attr("stroke","#0d1117").attr("stroke-width",1.5)
      .style("cursor","pointer")
      .on("mouseover", function(event) {
        d3.select(this).attr("opacity",1).attr("stroke","#e6edf3");
        tooltip
          .style("display","block")
          .html(`&lt;strong&gt;${d.model}&lt;/strong&gt;&lt;br&gt;
                 &lt;span style="color:${service_colors[d.service]}"&gt;${service_labels[d.service]}&lt;/span&gt;
                 &nbsp;·&nbsp; ${d.infra}&lt;br&gt;
                 Score: &lt;strong&gt;${d.overall_score.toFixed(2)}&lt;/strong&gt;&lt;br&gt;
                 TPS: &lt;strong&gt;${d.avg_tps.toFixed(0)}&lt;/strong&gt;&lt;br&gt;
                 Categories: ${d.categories_tested}`);
      })
      .on("mousemove", function(event) {
        tooltip.style("left",(event.clientX+14)+"px").style("top",(event.clientY-28)+"px");
      })
      .on("mouseout", function() {
        d3.select(this).attr("opacity",0.8).attr("stroke","#0d1117");
        tooltip.style("display","none");
      });

    // Label for notable outliers (very slow or very fast)
    if (d.avg_tps &gt; 150 || d.avg_tps &lt; 12 || d.model === "gpt-4o") {
      g.append("text")
        .attr("x", cx + r + 4).attr("y", cy + 4)
        .attr("font-size",9).attr("fill","#8b949e")
        .text(d.model.replace(":latest","").replace(":31b","·31b").substring(0,18));
    }
  });

  // Legend
  svcs.forEach((svc,i) =&gt; {
    g.append("circle").attr("cx", i*100).attr("cy", pH+46).attr("r",6)
     .attr("fill",service_colors[svc]).attr("opacity",0.85);
    g.append("text").attr("x", i*100+10).attr("y",pH+50)
     .attr("font-size",11).attr("fill","#8b949e").text(service_labels[svc]);
  });
  // Dot size legend
  g.append("text").attr("x",320).attr("y",pH+50)
   .attr("font-size",10).attr("fill","#6e7681")
   .text("Dot size = number of categories tested");

  return svg.node();
}

