      return `&lt;span style="font-size:0.72rem;color:#6e7681;background:rgba(255,255,255,0.05);padding:.1rem .4rem;border-radius:4px"&gt;programmatic&lt;/span&gt;`;
    if (j.includes("claude"))
      return `&lt;span style="font-size:0.72rem;color:#bc8cff;background:rgba(188,140,255,0.1);padding:.1rem .4rem;border-radius:4px"&gt;Claude&lt;/span&gt;`;
    return `&lt;span style="font-size:0.72rem;color:#58a6ff;background:rgba(88,166,255,0.1);padding:.1rem .4rem;border-radius:4px"&gt;Gemini&lt;/span&gt;`;
  }

  function latencyFmt(l) {
    return l &lt; 1 ? `${(l*1000).toFixed(0)}ms` : `${l.toFixed(1)}s`;
  }

  // Group by category
  const byCat = new Map();
  for (const r of rows) {
    if (!byCat.has(r.category)) byCat.set(r.category, []);
    byCat.get(r.category).push(r);
  }

  let html = `&lt;div style="margin-top:0.5rem"&gt;`;

  for (const [cat, catRows] of byCat) {
    const svcCol = service_colors[selected_service];
    html += `
      &lt;div style="margin-bottom:1.5rem"&gt;
        &lt;div style="font-size:0.78rem;font-weight:700;text-transform:uppercase;
                    letter-spacing:.08em;color:${svcCol};
                    border-bottom:1px solid #30363d;padding-bottom:.4rem;
                    margin-bottom:.5rem"&gt;
          ${cat_labels_map[cat] || cat}
        &lt;/div&gt;`;

    catRows.forEach(r =&gt; {
      // Truncate reason to ~180 chars
      const reason = r.reason ? r.reason.substring(0,200) + (r.reason.length &gt; 200 ? "…" : "") : "";

      html += `
        &lt;div style="display:grid;grid-template-columns:160px 48px 120px 90px 1fr;
                    gap:.5rem;align-items:start;
                    padding:.55rem .75rem;
                    border-radius:6px;
                    margin-bottom:3px;
                    background:rgba(255,255,255,0.02);
                    border:1px solid #30363d;
                    font-size:0.85rem"&gt;
          &lt;div style="color:#e6edf3;font-weight:500"&gt;${r.test_id}&lt;/div&gt;
          &lt;div style="text-align:center"&gt;${scoreHtml(r.score)}&lt;/div&gt;
          &lt;div&gt;${judgeTag(r.judge_model)}&lt;/div&gt;
          &lt;div style="color:#6e7681;font-size:0.8rem"&gt;
            ${latencyFmt(r.latency_sec)} &nbsp; ${r.tps.toFixed(0)} t/s
          &lt;/div&gt;
          &lt;div style="color:#8b949e;font-size:0.8rem;line-height:1.4"&gt;${reason}&lt;/div&gt;
        &lt;/div&gt;`;
    });

    html += `&lt;/div&gt;`;
  }

  html += `&lt;/div&gt;`;
  return htl.html([html]);
}

