{
  // Aggregate by category
  const agg = new Map();
  for (const r of canonical_tests) {
    if (!agg.has(r.category)) agg.set(r.category, []);
    agg.get(r.category).push(r.score);
  }

  const rows = cat_order
    .filter(c =&gt; agg.has(c))
    .map(c =&gt; {
      const scores = agg.get(c);
      const n  = scores.length;
      const mean = scores.reduce((a,b)=&gt;a+b,0)/n;
      const pct5 = Math.round(scores.filter(x=&gt;x===5).length/n*100);
      const min  = Math.min(...scores);
      return { cat: c, n, mean, pct5, min };
    });

  const html = `
    &lt;table style="width:100%;border-collapse:collapse"&gt;
      &lt;thead&gt;&lt;tr&gt;
        &lt;th&gt;Category&lt;/th&gt;
        &lt;th style="text-align:right"&gt;Tasks Run&lt;/th&gt;
        &lt;th style="text-align:right"&gt;Mean Score&lt;/th&gt;
        &lt;th style="text-align:right"&gt;% Perfect (5)&lt;/th&gt;
        &lt;th style="text-align:right"&gt;Min Score&lt;/th&gt;
        &lt;th&gt;Distribution&lt;/th&gt;
      &lt;/tr&gt;&lt;/thead&gt;
      &lt;tbody&gt;
        ${rows.map(r =&gt; {
          const scoreClass = r.mean &gt;= 4.5 ? "score-5" : r.mean &gt;= 3.5 ? "score-4" : "score-3";
          // Mini bar
          const bw = Math.round(r.pct5 * 1.4);
          const minibar = `&lt;div style="display:flex;align-items:center;gap:6px"&gt;
            &lt;div style="width:140px;height:10px;background:#1c2128;border-radius:5px;overflow:hidden"&gt;
              &lt;div style="width:${bw}px;height:10px;background:#1a7f37;border-radius:5px"&gt;&lt;/div&gt;
            &lt;/div&gt;
            &lt;span style="font-size:0.78rem;color:#6e7681"&gt;${r.pct5}% scored 5&lt;/span&gt;
          &lt;/div&gt;`;
          return `&lt;tr&gt;
            &lt;td style="font-weight:600"&gt;${cat_labels_map[r.cat]}&lt;/td&gt;
            &lt;td style="text-align:right;color:#8b949e"&gt;${r.n}&lt;/td&gt;
            &lt;td style="text-align:right"&gt;&lt;span class="${scoreClass}"&gt;${r.mean.toFixed(2)}&lt;/span&gt;&lt;/td&gt;
            &lt;td style="text-align:right;color:#8b949e"&gt;${r.pct5}%&lt;/td&gt;
            &lt;td style="text-align:right;color:${r.min&lt;=2?'#f85149':'#8b949e'}"&gt;${r.min}&lt;/td&gt;
            &lt;td&gt;${minibar}&lt;/td&gt;
          &lt;/tr&gt;`;
        }).join("")}
      &lt;/tbody&gt;
    &lt;/table&gt;`;
  return htl.html([html]);
